// Kenney CC0 sample integration + original Web Audio music and skill synthesis.
export class AudioManager {
 constructor(){this.context=null;this.buffers={};this.enabled=true;this.musicVolume=.22;this.sfxVolume=.6;this.last={};this.step=0;this.paused=true;}
 async init(){if(this.context){await this.context.resume();return;}this.context=new (window.AudioContext||window.webkitAudioContext)();this.master=this.context.createGain();this.master.gain.value=this.enabled?1:0;this.master.connect(this.context.destination);this.music=this.context.createGain();this.music.gain.value=this.musicVolume;this.music.connect(this.master);this.sfx=this.context.createGain();this.sfx.gain.value=this.sfxVolume;this.sfx.connect(this.master);for(const name of ['attack','hit','gate','break','zip'])fetch('./audio/'+name+'.ogg').then(r=>r.arrayBuffer()).then(b=>this.context.decodeAudioData(b)).then(b=>this.buffers[name]=b).catch(()=>{});this.timer=setInterval(()=>{if(!this.paused)this.musicTick();},450);}
 setEnabled(v){this.enabled=v;if(this.master)this.master.gain.value=v?1:0;}
 setVolume(bus,value){this[bus+'Volume']=value;if(this[bus])this[bus].gain.value=value;}
 tone(freq=440,duration=.15,bus='sfx',type='sine',volume=.1,slide=0){if(!this.context||this.context.state!=='running')return;const t=this.context.currentTime,osc=this.context.createOscillator(),gain=this.context.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,t);if(slide)osc.frequency.exponentialRampToValueAtTime(slide,t+duration);gain.gain.setValueAtTime(.001,t);gain.gain.exponentialRampToValueAtTime(Math.max(.001,volume),t+.012);gain.gain.exponentialRampToValueAtTime(.001,t+duration);osc.connect(gain);gain.connect(this[bus]);osc.start(t);osc.stop(t+duration+.01);osc.onended=()=>{gain.disconnect();osc.disconnect();};}
 play(name,hero=0){if(!this.context||this.paused)return;const t=this.context.currentTime;if(t-(this.last[name]??-9)<.065)return;this.last[name]=t;if(this.buffers[name]){const s=this.context.createBufferSource(),g=this.context.createGain();s.buffer=this.buffers[name];g.gain.value=name==='hit'?.4:.5;s.connect(g);g.connect(this.sfx);s.start();s.onended=()=>{g.disconnect();s.disconnect();};}
 if(name==='gun'){this.tone(hero==='狙击枪'?70:hero==='霰弹枪'?95:150,hero==='狙击枪'?.28:.1,'sfx','sawtooth',.1,35);this.tone(1100,.035,'sfx','triangle',.04,180);}if(name==='beep')this.tone(1250,.09,'sfx','sine',.12);if(name==='plant'){this.tone(260,.2,'sfx','triangle',.12,850);}if(name==='defuse'){this.tone(1200,.6,'sfx','sine',.12,350);}if(name==='reload')this.tone(350,.12,'sfx','square',.05,180);
 if(name==='impact'){this.tone(90,.35,'sfx','sawtooth',.12,32);this.tone(240,.15,'sfx','triangle',.1,65);}if(name==='cast'){this.tone([720,440,180,260,880][hero],.25,'sfx','triangle',.14,[1200,100,80,70,1320][hero]);}if(name==='level'){this.tone(660,.25,'sfx','sine',.14);setTimeout(()=>this.tone(990,.4,'sfx','sine',.13),100);}if(name==='hit')this.tone(150,.08,'sfx','triangle',.15,60);if(name==='kill'){[523,659,784].forEach((n,i)=>setTimeout(()=>this.tone(n,.23,'sfx','sine',.12),i*90));}if(name==='end'){[392,523,659,784].forEach((n,i)=>setTimeout(()=>this.tone(n,.8,'sfx','sine',.16),i*190));}if(name==='break')this.tone(80,.5,'sfx','sawtooth',.06,25);if(name==='zip')this.tone(260,.55,'sfx','triangle',.06,1100);if(name==='hit'&&!this.buffers.hit)this.tone(110,.06,'sfx','triangle',.1,45);}
 musicTick(){const notes=[196,246.94,293.66,392,329.63,293.66,246.94,220];const n=notes[this.step++%notes.length];this.tone(n,.9,'music','sine',.1);if(this.step%4===0){this.tone(n/2,1.7,'music','triangle',.045);this.tone(n*1.5,1.4,'music','sine',.035);}}
 pause(v){this.paused=v;}
}
